//! Repository for StockReconciliation entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written StockReconciliation SQL
//! (4-layer rule: services orchestrate, repositories hold the SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<StockReconciliation, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::PgPool;
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::StockReconciliation;

/// Table name for StockReconciliation entities
pub const TABLE_NAME: &str = "inventory.stock_reconciliations";

/// Repository for StockReconciliation entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct StockReconciliationRepository(
    backbone_orm::GenericCrudRepository<StockReconciliation, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for StockReconciliationRepository {
    type Target = backbone_orm::GenericCrudRepository<StockReconciliation, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl StockReconciliationRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a Stock Reconciliation header insert writes.
///
/// Mirrors the raw column shape rather than the `StockReconciliation` entity: `net_difference`
/// starts as a literal 0 (it is only known once every counted line is applied), and `status` /
/// `posting_state` are literal casts.
pub struct NewReconciliationRow<'a> {
    pub id: Uuid,
    pub recon_number: &'a str,
    pub company_id: Uuid,
    pub warehouse_id: Uuid,
    pub posting_date: chrono::NaiveDate,
    pub inventory_account_id: Uuid,
    pub adjustment_account_id: Uuid,
}

/// Hand-written StockReconciliation SQL. Lives here per the module's 4-layer rule.
impl StockReconciliationRepository {
    /// Insert the reconciliation header.
    ///
    /// Takes the CALLER'S connection so the header, its counted lines, and every bin/SLE write
    /// commit as one unit. The caller has already bound the company on it — don't re-bind here.
    ///
    /// Returns the raw `sqlx::Error` deliberately: the caller inspects it for a unique violation to
    /// turn a duplicate recon number into `DuplicateNumber`.
    pub async fn insert_submitted(
        &self,
        conn: &mut sqlx::PgConnection,
        r: &NewReconciliationRow<'_>,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO inventory.stock_reconciliations
                (id, recon_number, company_id, warehouse_id, posting_date, net_difference,
                 inventory_account_id, adjustment_account_id, status, posting_state)
               VALUES ($1,$2,$3,$4,$5,0,$6,$7,'submitted'::doc_status,'pending'::gl_posting_state)"#,
        )
        .bind(r.id).bind(r.recon_number).bind(r.company_id).bind(r.warehouse_id).bind(r.posting_date)
        .bind(r.inventory_account_id).bind(r.adjustment_account_id)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Record the net value difference the count produced. Must ride the movement's transaction.
    pub async fn update_net_difference(
        &self,
        conn: &mut sqlx::PgConnection,
        id: Uuid,
        net_difference: Decimal,
    ) -> Result<(), sqlx::Error> {
        sqlx::query("UPDATE inventory.stock_reconciliations SET net_difference=$2 WHERE id=$1")
            .bind(id).bind(net_difference)
            .execute(conn)
            .await?;
        Ok(())
    }

    /// Mark a zero-net reconciliation as needing no GL post at all (the count matched the books).
    ///
    /// Runs `execute_scoped` on the pool; the caller wraps it in `with_company_scope(Some(company))`
    /// so the UPDATE passes the RLS fence (ADR-0008).
    pub async fn mark_not_applicable(
        &self,
        pool: &PgPool,
        id: Uuid,
    ) -> Result<(), sqlx::Error> {
        company_scope::execute_scoped(
            pool,
            sqlx::query("UPDATE inventory.stock_reconciliations SET posting_state='not_applicable'::gl_posting_state WHERE id=$1")
                .bind(id),
        )
        .await?;
        Ok(())
    }
}

backbone_core::impl_crud_repository!(StockReconciliationRepository, StockReconciliation, soft_delete);
